{
  "name": "GRBL三轴运动控制板",
  "name_en": "GRBL 3-Axis Motion Controller",
  "manufacturer": "",
  "description": "一种基于 GRBL 固件并通过串口通信的运动控制板，用于驱动 X/Y/Z 三轴平台、滑台或简易 CNC/激光装置完成定位和移动。可进行归零、坐标移动、速度与加速度设置，并支持激光强度或 LED 输出控制，常用于实验室中的样品定位、扫描路径执行和自动化位移控制。",
  "description_en": "A serially controlled motion control board based on GRBL firmware, used to drive X/Y/Z stages, linear slides, or simple CNC/laser setups for positioning and motion. It supports homing, coordinate moves, speed and acceleration settings, and control of laser intensity or LED output, making it useful in laboratories for sample positioning, scan-path execution, and automated translation tasks.",
  "tag_hints": [
    "GRBL motion control",
    "XYZ positioning",
    "serial CNC controller",
    "motorized stage control",
    "G-code motion",
    "laser intensity control",
    "automated sample positioning"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与运动控制板的串口连接。",
      "description_en": "Close the serial connection to the motion controller."
    },
    {
      "action_name": "auto-initserial",
      "description": "初始化串口连接并设置初始原点坐标。",
      "description_en": "Initialize the serial connection and set the initial home coordinates."
    },
    {
      "action_name": "auto-zero_position",
      "description": "将当前位置设为零点。",
      "description_en": "Set the current position as zero."
    },
    {
      "action_name": "auto-auto_detect_serial_unix",
      "description": "在类 Unix 系统上自动检测可用的控制板串口。",
      "description_en": "Auto-detect available serial ports for the controller on Unix-like systems."
    },
    {
      "action_name": "auto-setideltime",
      "description": "设置设备空闲时间参数。",
      "description_en": "Set the device idle-time parameter."
    },
    {
      "action_name": "auto-setspeed",
      "description": "设置运动速度。",
      "description_en": "Set the motion speed."
    },
    {
      "action_name": "auto-setaccellaration",
      "description": "设置运动加速度。",
      "description_en": "Set the motion acceleration."
    },
    {
      "action_name": "auto-setphysicalcoords",
      "description": "定义运动系统的物理坐标参数。",
      "description_en": "Define the physical coordinate parameters of the motion system."
    },
    {
      "action_name": "auto-resethome",
      "description": "重置原点位置。",
      "description_en": "Reset the home position."
    },
    {
      "action_name": "auto-getcurrentpos",
      "description": "获取当前坐标位置。",
      "description_en": "Get the current position coordinates."
    },
    {
      "action_name": "auto-sendgrbl",
      "description": "向控制板发送原始 GRBL/G 代码命令。",
      "description_en": "Send a raw GRBL/G-code command to the controller."
    },
    {
      "action_name": "auto-move_rel",
      "description": "按相对位移移动。",
      "description_en": "Move by a relative offset."
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动到绝对坐标位置。",
      "description_en": "Move to an absolute coordinate position."
    },
    {
      "action_name": "auto-set_units",
      "description": "设置运动单位为公制或英制。",
      "description_en": "Set the motion units to metric or imperial."
    },
    {
      "action_name": "auto-go_to",
      "description": "以绝对或相对模式移动到指定坐标。",
      "description_en": "Move to the specified coordinates in absolute or relative mode."
    },
    {
      "action_name": "auto-set_laser_intensity",
      "description": "设置激光输出强度。",
      "description_en": "Set the laser output intensity."
    },
    {
      "action_name": "auto-set_led",
      "description": "设置 LED 输出开关状态。",
      "description_en": "Set the LED output on/off state."
    }
  ]
}

